<script setup lang="ts">
import { defineAsyncComponent, h, type Component, onBeforeUnmount, onMounted, ref, computed } from 'vue'
import type { Workspace } from './api'
import Icon from './Icon.vue'
import { scenarioContextHref } from './scenario-context'
function panel(loader:()=>Promise<{default:Component}>){return defineAsyncComponent({loader,delay:0,loadingComponent:()=>h('p',{class:'message',role:'status'},'正在载入工具…'),timeout:20000,errorComponent:()=>h('section',{class:'message message-error',role:'alert'},[h('p','工具资源暂时无法载入，请检查网络连接。'),h('button',{type:'button',class:'button button-secondary',onClick:()=>window.location.reload()},'重新载入页面')])})}
const BrowserAnnotationsPanel=panel(()=>import('./BrowserAnnotationsPanel.vue'))
const FileDiscoveryPanel=panel(()=>import('./FileDiscoveryPanel.vue'))
const ValueSearchPanel=panel(()=>import('./ValueSearchPanel.vue'))
const ClassificationKnowledgePanel=panel(()=>import('./ClassificationKnowledgePanel.vue'))
const OperationsReportsPanel=panel(()=>import('./OperationsReportsPanel.vue'))
const ClassificationDeliveryPanel=panel(()=>import('./ClassificationDeliveryPanel.vue'))
const ClassificationTrainingPanel=panel(()=>import('./ClassificationTrainingPanel.vue'))
const DataSecurityPanel=panel(()=>import('./DataSecurityPanel.vue'))
const props=defineProps<{workspace:Workspace}>();const emit=defineEmits<{sessionExpired:[]}>()
const tabs=[{id:'browser',label:'浏览器字段标注'},{id:'files',label:'文件接入'},{id:'value-search',label:'数据指纹溯源'},{id:'knowledge',label:'分类知识'},{id:'training',label:'本地模型训练'},{id:'delivery',label:'发布交付'},{id:'reports',label:'运营报告'},{id:'data-security',label:'数据外发与调查'}]
function read(){const value=new URLSearchParams(location.hash.split('?')[1]||'').get('tab');return tabs.find(t=>t.id===value)?.id||'browser'}
const capabilityDetails: Record<string,{icon:string;title:string;stages:string[];input:string;output:string;boundary:string}>={
 browser:{icon:'api-lifecycle',title:'浏览器辅助打标',stages:['选中页面字段','形成接口字段候选','人工核对并采用'],input:'显式选择的结构化字段元数据',output:'候选关联、来源引用与人工确认',boundary:'不采完整页面正文或输入值；同名候选不代表已证实 DOM 到 API 血缘。'},
 files:{icon:'reports',title:'授权文件内容识别',stages:['明确文件授权','客户侧有界识别','核对命中与覆盖缺口'],input:'已授权的文件及预算范围',output:'类型命中、来源摘要与覆盖限制',boundary:'仅处理明确授权的文件范围，不推导未接入目录或任意格式的识别质量。'},
 'value-search':{icon:'search',title:'源端指纹溯源',stages:['建立等值查询','客户侧来源查找','核对命中与显式关系'],input:'源端 HMAC 等值查询 token',output:'来源命中与有证据的转换关系',boundary:'不上传具体值原文，不表示通用解密或自动补全内部数据链路。'},
 knowledge:{icon:'classification',title:'分类知识与引用',stages:['检索知识引用','核对来源版本','授权辅助建议'],input:'版本化本地知识与依据引用',output:'检索记录、候选建议与采用历史',boundary:'知识和模型建议不自动成为人工确认；外部模型调用按次授权。'},
 training:{icon:'automation',title:'本地模型训练',stages:['划分授权样本','可复现本地训练','独立留出与资产预测'],input:'授权样本、划分与训练配置',output:'运行、留出结果及实际预测记录',boundary:'训练完成不代表生产采用，独立评估不能外推到未测来源。'},
 delivery:{icon:'integrations',title:'冻结发布与交付',stages:['固定采用快照','客户侧执行','核对接收回执'],input:'已批准的冻结发布版本',output:'交付记录、目标与接收回执',boundary:'收到发布内容不表示第三方标签已写入，缺少执行证据的阶段保持未完成。'},
 reports:{icon:'reports',title:'运营技术报告',stages:['明确窗口与来源','核对实际采用证据','冻结报告与缺项'],input:'明确来源、实际窗口与证据范围',output:'可下载技术快照及完整缺项',boundary:'有限审计窗口不等于完整月度日志，内部报告形成不等于正式对外提交。'},
 'data-security':{icon:'shield',title:'外发与终端调查',stages:['核对来源事件','受控动作与回执','新观察与功能验证'],input:'授权来源、事件及准确目标',output:'阶段回执、复测与独立核验依据',boundary:'原生配置、主动集成与用户会话响应范围不同；Windows 功能仍需真实设备证据。'},
}
const tab=ref(read());const current=computed(()=>capabilityDetails[tab.value]!);function openTool(){document.getElementById('capability-tool-body')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}function changed(){tab.value=read()}
function choose(id:string){
  const oldURL=window.location.href
  const url=new URL(oldURL),[path,query='']=url.hash.split('?'),params=new URLSearchParams(query)
  params.set('tab',id);params.delete('annotation');url.hash=path+'?'+params
  window.history.replaceState(window.history.state,'',url)
  tab.value=id
  window.dispatchEvent(new HashChangeEvent('hashchange',{oldURL,newURL:url.href}))
}
onMounted(()=>window.addEventListener('hashchange',changed));onBeforeUnmount(()=>window.removeEventListener('hashchange',changed))
</script>
<template><section class="capability-tools"><header class="page-header"><div><p class="eyebrow">{{tab==='data-security'?'场景结果 / 数据安全运营':'专业工具与配置 / 识别与证据能力'}}</p><h1>{{tab==='data-security'?'外发事件需要哪些证据？':'从识别线索，走到可采用的证据'}}</h1><p>{{tab==='data-security'?'核对已接入来源的外发与审计事件，冻结调查证据，保留研判反馈。':'配置业务页面标注、文件发现、指纹查询和自有识别能力。结果保留实际来源、人工关联与版本依据。'}}</p></div><a class="button" :href="scenarioContextHref(workspace.slug,tab==='data-security'?'operations':'classification')">{{tab==='data-security'?'查看运营与处置':'返回分类分级'}}</a></header><nav class="capability-tabs" aria-label="识别与证据工具"><button v-for="item in tabs" :key="item.id" type="button" :class="{active:tab===item.id}" :aria-pressed="tab===item.id" @click="choose(item.id)"><Icon :name="capabilityDetails[item.id]!.icon" />{{item.label}}</button></nav><div class="capability-composition"><section class="panel capability-transform"><div class="panel-heading"><div><h2>{{ current.title }}的证据路径</h2><p>能力路径说明 · 实际来源与运行结果在下方工具中核对</p></div></div><ol class="capability-chain"><li v-for="(stage,index) in current.stages" :key="stage"><span>{{ index+1 }}</span><Icon :name="[current.icon,'classification','checks'][index]!"/><strong>{{ stage }}</strong><small>{{ index===0?current.input:index===1?'保留来源、范围与实际版本':current.output }}</small></li></ol><dl class="capability-contract"><div><dt>输入</dt><dd>{{ current.input }}</dd></div><div><dt>输出</dt><dd>{{ current.output }}</dd></div></dl></section><aside class="panel capability-boundary"><h2>当前能力：{{ current.title }}</h2><div><h3>采用边界</h3><p>{{ current.boundary }}</p></div><p>下方工具展示真实记录及可用操作。没有来源记录时保留空态和未知，能力路径不表示运行完成。</p><button type="button" class="button button-primary" @click="openTool">打开{{ current.title }}工具</button></aside></div><div id="capability-tool-body" class="capability-tool-body"><BrowserAnnotationsPanel v-if="tab==='browser'" :workspace="workspace" @session-expired="emit('sessionExpired')"/><FileDiscoveryPanel v-else-if="tab==='files'" :workspace="workspace" @session-expired="emit('sessionExpired')"/><ValueSearchPanel v-else-if="tab==='value-search'" :workspace="workspace" @session-expired="emit('sessionExpired')"/><ClassificationKnowledgePanel v-else-if="tab==='knowledge'" :workspace="workspace" @session-expired="emit('sessionExpired')"/><ClassificationTrainingPanel v-else-if="tab==='training'" :workspace="workspace" @session-expired="emit('sessionExpired')"/><ClassificationDeliveryPanel v-else-if="tab==='delivery'" :workspace="workspace" @session-expired="emit('sessionExpired')"/><DataSecurityPanel v-else-if="tab==='data-security'" :workspace="workspace" @session-expired="emit('sessionExpired')"/><OperationsReportsPanel v-else-if="tab==='reports'" :workspace="workspace" @session-expired="emit('sessionExpired')"/></div></section></template>
<style scoped>.capability-tools{display:grid;gap:20px;min-width:0}.capability-tools .page-header{margin:0}.capability-tabs{display:flex;flex-wrap:wrap;border-bottom:1px solid var(--line);gap:4px}.capability-tabs button{border:0;border-bottom:2px solid transparent;background:none;color:var(--secondary);padding:13px 14px;font:inherit;font-size:12px;cursor:pointer}.capability-tabs button.active{border-bottom-color:var(--accent);color:var(--accent);font-weight:700}</style>

<style scoped>.capability-tabs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;border:1px solid var(--line);border-radius:9px;background:white;padding:14px}.capability-tabs button{display:flex;align-items:center;justify-content:center;gap:12px;padding:13px;background:var(--surface-subtle);border:1px solid var(--line);border-radius:6px;font-size:14px;color:var(--ink)}.capability-tabs button.active{background:var(--accent-soft);border:1px solid var(--accent)}.capability-tabs .icon{width:23px;height:23px;color:var(--accent)}.capability-composition{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:16px}.capability-composition>.panel{min-width:0}.capability-chain{list-style:none;display:flex;gap:32px;padding:22px;margin:0}.capability-chain li{position:relative;display:grid;grid-template-columns:28px 1fr;align-content:start;gap:12px;background:#f3f9fe;border:1px solid #c7dfeF;border-radius:8px;padding:16px;flex:1;min-width:0}.capability-chain li>span{display:grid;place-items:center;width:26px;height:26px;border-radius:50%;background:#e0edf6;color:#315d7e;font-weight:700}.capability-chain li>.icon{justify-self:end;width:35px;height:35px;color:var(--accent)}.capability-chain strong,.capability-chain small{grid-column:1/-1;line-height:1.8}.capability-chain strong{font-size:15px}.capability-chain small{font-size:12px;color:var(--secondary)}.capability-chain li:not(:last-child)::after{content:'→';position:absolute;left:calc(100% + 8px);top:55px;color:var(--accent)}.capability-contract{margin:0 22px 22px;border:1px solid var(--line);border-radius:6px}.capability-contract>div{display:grid;grid-template-columns:80px minmax(0,1fr);gap:12px;padding:12px 14px;font-size:13px}.capability-contract>div+div{border-top:1px solid var(--line)}.capability-contract dt{color:var(--secondary)}.capability-contract dd{margin:0}.capability-boundary{padding:22px;display:flex;flex-direction:column;align-items:flex-start;gap:16px}.capability-boundary h2{font-size:17px;line-height:1.7;margin:0}.capability-boundary>div{padding:14px;background:#fff6e6;border:1px solid #ecd7ad;border-radius:7px}.capability-boundary h3{font-size:14px;margin:0 0 8px;color:#8a5416}.capability-boundary p{font-size:12px;line-height:1.9;color:var(--secondary);margin:0}.capability-boundary .button{margin-top:auto}.capability-tool-body{scroll-margin-top:24px;min-width:0}@media(max-width:1250px){.capability-composition{grid-template-columns:minmax(0,1fr) 280px}.capability-chain{padding:16px;gap:22px}.capability-chain li{padding:13px}.capability-chain li:not(:last-child)::after{left:calc(100% + 3px)}}@media(max-width:850px){.capability-composition{grid-template-columns:1fr}.capability-tabs{grid-template-columns:repeat(2,minmax(0,1fr))}.capability-chain{flex-wrap:wrap}.capability-chain li{flex-basis:100%}.capability-chain li::after{display:none}}</style>
